#!/usr/bin/env Rscript

suppressPackageStartupMessages({ library(Matrix) })

args <- commandArgs(trailingOnly = TRUE)
if (length(args) != 3) stop("usage: galaxy_celltype_diag.R eye1.mtx.gz eye2.mtx.gz genes.txt.gz")
eye1_path <- args[[1]]
eye2_path <- args[[2]]
genes_path <- args[[3]]

read_mtx_gz <- function(path) {
  con <- gzfile(path, open = "rt")
  on.exit(close(con), add = TRUE)
  as(Matrix::readMM(con), "dgCMatrix")
}

read_gene_symbols <- function(path) {
  con <- gzfile(path, open = "rt")
  on.exit(close(con), add = TRUE)
  z <- readLines(con, warn = FALSE)
  if (length(z) < 2L) stop("gene file has no data rows")
  p <- strsplit(z[-1L], "\t", fixed = TRUE)
  out <- vapply(p, function(x) {
    if (length(x) >= 2L && nzchar(x[[2L]])) x[[2L]] else x[[1L]]
  }, character(1))
  make.unique(out)
}

